import{_ as a,a0 as r,w as d,s as p,ao as n,I as t,x as o,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 FreeDOS 中設置和使用環境變量 | LCTT x X-CMD","titleTemplate":false,"description":"在 FreeDOS 中設置和使用環境變量 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 FreeDOS 中設置和使用環境變量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 FreeDOS 中設置和使用環境變量 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20210604 Set and use environment variables in FreeDOS","title":"在 FreeDOS 中設置和使用環境變量","tag":"202111","desc":""},"relativePath":"202111/20210604 Set and use environment variables in FreeDOS.md","filePath":"[post].md"}'),c={name:"202111/20210604 Set and use environment variables in FreeDOS.md"};function u(S,e,m,b,D,f){const s=r("Link");return d(),p("div",null,[e[22]||(e[22]=n('<h1 id="在-freedos-中設置和使用環境變量" tabindex="-1">在 FreeDOS 中設置和使用環境變量 <a class="header-anchor" href="#在-freedos-中設置和使用環境變量" aria-label="Permalink to “在 FreeDOS 中設置和使用環境變量”">​</a></h1><blockquote><p>環境變量幾乎在每種命令列環境中都是很有幫助的，自然包括 FreeDOS 。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/18/152155twzasgwwrzsmmvs2.jpg" alt=""></p><p>幾乎在每個命令列環境中的一個有用的功能是 <em>環境變量</em>。其中的一些變量允許你控制命令列的行為或功能，其它的變量僅允許你存儲可能稍後需要的數據，在 FreeDOS 中也使用了環境變量。</p><h3 id="在-linux-上的變量" tabindex="-1">在 Linux 上的變量 <a class="header-anchor" href="#在-linux-上的變量" aria-label="Permalink to “在 Linux 上的變量”">​</a></h3>',5)),t("p",null,[e[1]||(e[1]=o("在 Linux 上，你可能已經熟悉其中的一些重要的環境變量。在 Linux 上的 ",-1)),l(s,{href:"https://opensource.com/article/19/8/using-variables-bash"},{default:i(()=>[...e[0]||(e[0]=[o("Bash",-1)])]),_:1}),e[2]||(e[2]=o(" shell 中，",-1)),e[3]||(e[3]=t("code",null,"PATH",-1)),e[4]||(e[4]=o(" 變量標示着 shell 可以在哪裏找到程序和命令。例如，在我的 Linux 系統上，我的  ",-1)),e[5]||(e[5]=t("code",null,"PATH",-1)),e[6]||(e[6]=o(" 值如下：",-1))]),e[23]||(e[23]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash$ echo $PATH</span></span>
<span class="line"><span>/home/jhall/bin:/usr/lib64/ccache:/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin</span></span></code></pre></div><p>這意味着，當我輸入一個像 <code>cat</code> 這樣的命令的名稱時，Bash 將會按順序檢查我在 <code>PATH</code> 變量中所列出的每個目錄：</p><ol><li><code>/home/jhall/bin</code></li><li><code>/usr/lib64/ccache</code></li><li><code>/usr/local/bin</code></li><li><code>/usr/local/sbin</code></li><li><code>/usr/bin</code></li><li><code>/usr/sbin</code></li></ol><p>在我的實例中，<code>cat</code> 命令位於 <code>/usr/bin</code> 目錄，因此，完整的路徑是 <code>/usr/bin/cat</code> 。</p><p>為在 Linux 上設置一個環境變量，你可以輸入一個變量的名稱，接着輸入一個等於符號（<code>=</code>），接着輸入一個要存儲在變量中的值。為了隨後使用 Bash 引用這個值，你需要在變量的名稱前輸入一個美元符號（<code>$</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash$ var=Hello</span></span>
<span class="line"><span>bash$ echo $var</span></span>
<span class="line"><span>Hello</span></span></code></pre></div><h3 id="在-freedos-上的變量" tabindex="-1">在 FreeDOS 上的變量 <a class="header-anchor" href="#在-freedos-上的變量" aria-label="Permalink to “在 FreeDOS 上的變量”">​</a></h3><p>在 FreeDOS 上，環境變量提供一種類似的功能。一些變量控制 DOS 系統的行為，另一些變量用於存儲一些臨時值。</p><p>為在 FreeDOS 上設置一個環境變量，你需要使用 <code>SET</code> 關鍵字。FreeDOS 是 <em>不區分大小寫的</em> ，因此你可以輸入大寫字母也可以使用小寫字母。接下來，像你在 Linux 上一樣設置變量，使用變量名稱，一個等於符號（<code>=</code>），你想要存儲的值。</p><p>不過，在 FreeDOS 中引用或 <em>擴展</em> 一個環境變量的值的方法，與你在 Linux 上所使用的方法是完全不同的。在 FreeDOS 中，你不能使用美元符號（<code>$</code>）來引用一個變量。你反而需要使用百分符號 （<code>%</code>）來包圍變量的名稱。</p><p><img src="https://opensource.com/sites/default/files/uploads/env-path.png" alt="Use % (not $) to reference a variable&#39;s value"></p><p>在名稱前後使用百分符號是非常重要，因為這就是 FreeDOS 知悉變量名稱在哪裏開始和結束的方式。這是非常有用的，因為它會允許你引用一個變量的值，與此同時，它會立即附加（或預置）其它的文本到值中。讓我通過設置一個新的名稱為 <code>reply</code> 的值為 <code>yes</code> 的變量，然後在 “11” 之前和 “22” 之後引用這個值來演示這一點：</p><p><img src="https://opensource.com/sites/default/files/uploads/env-vars.png" alt="Set and reference an environment variable"></p><p>因為 FreeDOS 是不區分大小寫的，所以你可以使用大寫字母稱或小寫字母的變量名稱以及 <code>SET</code> 關鍵字。不過，變量的值將使用你在命令列中所輸入的字母。</p><p>最後，你可以看到當前在 FreeDOS 中定義的所有的環境變量。不使用任何參數的 <code>SET</code> 關鍵字將顯示所有的變量，因此你可以一目瞭然：</p><p><img src="https://opensource.com/sites/default/files/uploads/env-set.png" alt="Show all variables at once with SET"></p><p>環境變量是一個有用的基本的命令列環境，同樣適用於 FreeDOS 。你可以設置你自己的變量以滿足你自己的需要，但是要仔細地更改 FreeDOS 使用的一些變量。這些變量會更改你正在運行的 FreeDOS 系統的行為：</p><ul><li><code>DOSDIR</code>：FreeDOS 安裝目錄的位置，通常是 <code>C:\\FDOS</code></li><li><code>COMSPEC</code>：FreeDOS 的 shell 的當前實例，通常是 <code>C:\\COMMAND.COM</code> 或 <code>%DOSDIR%\\BIN\\COMMAND.COM</code></li><li><code>LANG</code>：用户的首選語言</li><li><code>NLSPATH</code>：系統語言文件的位置，通常是 <code>%DOSDIR%\\NLS</code></li><li><code>TZ</code>：系統的時區</li><li><code>PATH</code>：一個目錄列表，FreeDOS 可以在其中找到要運行的程序，例如 <code>%DOSDIR%\\BIN</code></li><li><code>HELPPATH</code>：系統文檔文件的位置，通常是 <code>%DOSDIR%\\HELP</code></li><li><code>TEMP</code>：一個臨時目錄，FreeDOS 在其中存儲來自每個命令的輸出，如同它在命令列上的程序之間的 “管道” 數據</li><li><code>DIRCMD</code>：一個控制 <code>DIR</code> 命令如何顯示文件和目錄的變量，通常設置 <code>/OGNE</code> 來排序（<code>O</code>）內容，先通過分組（<code>G</code>）目錄，接下來按照名稱（<code>N</code>） 、擴展名（<code>E</code>）來排序條目</li></ul><p>如果你偶然間更改了任意的 FreeDOS 的 “內部” 變量，你可能會阻礙 FreeDOS 的一些部分的正常工作。在這種情況下，只需要簡單地重新啓動你的計算機，FreeDOS 將會按照系統默認值重新設置變量。</p><hr>`,20)),t("p",null,[e[8]||(e[8]=o("via: ",-1)),l(s,{href:"https://opensource.com/article/21/6/freedos-environment-variables"},{default:i(()=>[...e[7]||(e[7]=[o("https://opensource.com/article/21/6/freedos-environment-variables",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=o("作者：",-1)),l(s,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...e[9]||(e[9]=[o("Jim Hall",-1)])]),_:1}),e[14]||(e[14]=o(" 選題：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[10]||(e[10]=[o("lujun9972",-1)])]),_:1}),e[15]||(e[15]=o(" 譯者：",-1)),l(s,{href:"https://github.com/robsean"},{default:i(()=>[...e[11]||(e[11]=[o("robsean",-1)])]),_:1}),e[16]||(e[16]=o(" 校對：",-1)),l(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[12]||(e[12]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=o("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[17]||(e[17]=[o("LCTT",-1)])]),_:1}),e[20]||(e[20]=o(" 原創編譯，",-1)),l(s,{href:"https://linux.cn/"},{default:i(()=>[...e[18]||(e[18]=[o("Linux中國",-1)])]),_:1}),e[21]||(e[21]=o(" 榮譽推出",-1))])])}const g=a(c,[["render",u]]);export{T as __pageData,g as default};
